package com.fasterxml.jackson.core.io;

import com.fasterxml.jackson.core.JsonEncoding;
import com.fasterxml.jackson.core.util.BufferRecycler;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for IOContext._verifyRelease.
 * Since the method is protected, we use reflection or a subclass to access it.
 */
public class IOContext__verifyRelease_TriageGen2Test {

    private IOContext ioContext;
    private BufferRecycler bufferRecycler;

    @Before
    public void setUp() {
        bufferRecycler = new BufferRecycler();
        ioContext = new IOContext(bufferRecycler, null, false);
    }

    /**
     * Helper method to invoke the protected _verifyRelease method via reflection.
     */
    private void invokeVerifyRelease(byte[] toRelease, byte[] src) throws Exception {
        Method method = IOContext.class.getDeclaredMethod("_verifyRelease", byte[].class, byte[].class);
        method.setAccessible(true);
        try {
            method.invoke(ioContext, toRelease, src);
        } catch (java.lang.reflect.InvocationTargetException e) {
            // Throw the actual cause (the exception thrown by the method)
            throw (Exception) e.getCause();
        }
    }

    @Test
    public void testVerifyRelease_SameBuffer_ShouldNotThrow() throws Exception {
        byte[] buffer = new byte[10];
        // If toRelease == src, the condition (toRelease != src) is false, should not throw
        invokeVerifyRelease(buffer, buffer);
    }

    @Test
    public void testVerifyRelease_DifferentBufferLarger_ShouldNotThrow() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[11];
        // Different buffers and toRelease.length > src.length -> condition false
        invokeVerifyRelease(toRelease, src);
    }

    @Test
    public void testVerifyRelease_DifferentBufferSmaller_ShouldThrow() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[5];
        // Different buffers and toRelease.length < src.length -> condition true
        assertThrows(IllegalArgumentException.class, () -> {
            invokeVerifyRelease(toRelease, src);
        });
    }

    @Test
    public void testVerifyRelease_DifferentBufferEqualLength_ShouldThrow() throws Exception {
        byte[] src = new byte[10];
        byte[] toRelease = new byte[10];
        // Different buffers and toRelease.length == src.length -> condition true
        // Note: The code says (toRelease.length <= src.length), so equal length triggers exception
        assertThrows(IllegalArgumentException.class, () -> {
            invokeVerifyRelease(toRelease, src);
        });
    }
}
